import { expect, test } from "bun:test";
import Ajv from "ajv@^8.17.1";

const validate = new Ajv({ allErrors: true }).compile({
  type: "object",
  definitions: { positive: { type: "integer", minimum: 1 } },
  properties: {
    values: { type: "array", items: { $ref: "#/definitions/positive" } },
    state: { enum: ["ready", "done"] },
    marker: { const: { owned: true } },
  },
  required: ["values", "state", "marker"],
  additionalProperties: false,
});
test("real cached validator accepts valid nested references and rejects invalid values", () => {
  expect(validate({ values: [1, 2], state: "done", marker: { owned: true } })).toBe(true);
  expect(validate({ values: [0], state: "done", marker: { owned: true } })).toBe(false);
  expect(validate({ values: [1], state: "unknown", marker: { owned: true } })).toBe(false);
  expect(validate({ values: [1], state: "done", marker: { owned: false } })).toBe(false);
});
